const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const beledweyne = ee.Geometry.Point(45.2026, 4.7339);
  const region = beledweyne.buffer(20000); // 20 km buffer around Beledweyne

  const start2017 = '2017-05-01';
  const end2017 = '2017-05-31';
  const start2018 = '2018-05-01';
  const end2018 = '2018-05-31';

  const SMAP_COLLECTION = 'NASA/SMAP/SPL3SMP_E_005';
  const BAND_NAME = 'soil_moisture';
  const SCALE = 10000; // SMAP resolution is ~9km, using 10km scale

  // Function to mask low quality pixels
  const maskSmapQuality = function(image) {
    const qualityFlag = image.select('retrieval_qual_flag');
    // retrieval_qual_flag == 0 indicates good quality
    const goodQuality = qualityFlag.eq(0);

    // Also mask out fill value -9999
    const soilMoisture = image.select(BAND_NAME);
    const validSoilMoisture = soilMoisture.neq(-9999);

    return image.updateMask(goodQuality.and(validSoilMoisture));
  };

  // 2. Data Acquisition & Check for 2017
  let col2017 = ee.ImageCollection(SMAP_COLLECTION)
    .filterDate(start2017, end2017)
    .filterBounds(region)
    .map(maskSmapQuality)
    .select(BAND_NAME);

  const size2017 = await col2017.size().getInfo();
  if (size2017 === 0) {
    console.log("No SMAP images found for May 2017 in the specified region.");
    console.log("C1");
    return;
  }

  // Data Acquisition & Check for 2018
  let col2018 = ee.ImageCollection(SMAP_COLLECTION)
    .filterDate(start2018, end2018)
    .filterBounds(region)
    .map(maskSmapQuality)
    .select(BAND_NAME);

  const size2018 = await col2018.size().getInfo();
  if (size2018 === 0) {
    console.log("No SMAP images found for May 2018 in the specified region.");
    console.log("C1");
    return;
  }

  // 3. Processing: Calculate mean soil moisture for each period
  const meanImage2017 = col2017.mean();
  const meanImage2018 = col2018.mean();

  // Calculate pixel count to detect C2
  const count2017 = await meanImage2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: SCALE,
    maxPixels: 1e9
  }).get(BAND_NAME).getInfo();

  if (count2017 === 0) {
    console.log("2017 Images: " + size2017);
    console.log("No valid pixels for 2017 after masking within the region.");
    console.log("C2");
    return;
  }

  const count2018 = await meanImage2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: SCALE,
    maxPixels: 1e9
  }).get(BAND_NAME).getInfo();

  if (count2018 === 0) {
    console.log("2018 Images: " + size2018);
    console.log("No valid pixels for 2018 after masking within the region.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const soilMoisture2017 = await meanImage2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: SCALE,
    maxPixels: 1e9
  }).get(BAND_NAME).getInfo();

  const soilMoisture2018 = await meanImage2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: SCALE,
    maxPixels: 1e9
  }).get(BAND_NAME).getInfo();

  // 5. Validation & Final Answer
  if (soilMoisture2017 === null || isNaN(soilMoisture2017) ||
      soilMoisture2018 === null || isNaN(soilMoisture2018)) {
    console.log("Calculation resulted in None or NaN.");
    console.log("C3");
    return;
  }

  console.log(`2017 Images: ${size2017} (Valid Pixels: ${count2017})`);
  console.log(`2018 Images: ${size2018} (Valid Pixels: ${count2018})`);
  console.log(`Mean Soil Moisture May 2017: ${soilMoisture2017.toFixed(4)} m^3/m^3`);
  console.log(`Mean Soil Moisture May 2018: ${soilMoisture2018.toFixed(4)} m^3/m^3`);

  if (soilMoisture2018 > soilMoisture2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
